package pe.eltumi.erp;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.time.*;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import static pe.eltumi.erp.Store.*;
@RestController @RequestMapping("/api/auth")
public class AuthController {
 final Store db;final BCryptPasswordEncoder encoder;final Access access;
 public AuthController(Store db,BCryptPasswordEncoder encoder,Access access){this.db=db;this.encoder=encoder;this.access=access;}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,Object>b){String email=str(b,"email").toLowerCase(Locale.ROOT);String password=str(b,"password");require(email.length()<256&&password.length()<200,"Datos inválidos");var rows=db.rows("SELECT * FROM users WHERE email=?",email);if(rows.isEmpty()){encoder.matches(password,"$2a$12$skMCWpOIilPRLQAN1tjkFup.X.R.rnUbZSNiPiN4JKCIF1ASagRqG");throw new Problem(401,"Correo o contraseña incorrectos");}var u=rows.get(0);if(!str(u,"status").equals("ACTIVO"))throw new Problem(401,"Usuario no disponible");String locked=str(u,"locked_until");if(!locked.isEmpty()&&LocalDateTime.parse(locked).isAfter(LocalDateTime.now()))throw new Problem(429,"Espera 15 minutos antes de intentarlo nuevamente");boolean totp=Boolean.TRUE.equals(u.get("totp_enabled"))||"1".equals(str(u,"totp_enabled"));if(!encoder.matches(password,str(u,"password_hash"))||(totp&&!validTotp(str(u,"totp_secret"),str(b,"otp")))){int fail=(int)id(u,"failed_attempts")+1;db.update("users",id(u,"id"),map("failed_attempts",fail,"locked_until",fail>=5?LocalDateTime.now().plusMinutes(15):null));throw new Problem(401,totp?"Credenciales o código de autenticación incorrectos":"Correo o contraseña incorrectos");}db.update("users",id(u,"id"),map("failed_attempts",0,"locked_until",null));db.exec("DELETE FROM sessions WHERE expires_at<CURRENT_TIMESTAMP");String t=Security.token();db.insert("sessions",map("token_hash",Security.hash(t),"user_id",id(u,"id"),"expires_at",LocalDateTime.now().plusHours(8)));db.insert("audit",map("username",email,"action","LOGIN","entity","users","entity_id",id(u,"id"),"detail","Inicio de sesión"));return map("token",t,"user",safe(u),"permissions",permissions(str(u,"role")));}
 Map<String,Object> safe(Map<String,Object>u){return map("id",u.get("id"),"name",u.get("name"),"email",u.get("email"),"role",u.get("role"),"totp_enabled",u.get("totp_enabled"));}
 List<Map<String,Object>> permissions(String role){if(role.equals("ADMIN"))return List.of();return db.rows("SELECT module,can_read,can_write,can_approve,can_export FROM permissions WHERE role=?",role);}
 @GetMapping("/me") public Map<String,Object> me(){return map("user",safe(db.get("users",Security.user().id())),"permissions",permissions(Security.user().role()));}
 @PostMapping("/logout")public void logout(HttpServletRequest req){db.exec("DELETE FROM sessions WHERE token_hash=?",Security.hash(req.getHeader("Authorization").substring(7)));}
 @PostMapping("/password")public void password(@RequestBody Map<String,Object>b){var u=db.get("users",Security.user().id());require(encoder.matches(str(b,"current"),str(u,"password_hash")),"La contraseña actual no coincide");String p=str(b,"password");require(p.length()>=10&&p.length()<=72,"Usa entre 10 y 72 caracteres");db.update("users",Security.user().id(),map("password_hash",encoder.encode(p)));db.exec("DELETE FROM sessions WHERE user_id=?",Security.user().id());}
 @PostMapping("/totp/setup")public Map<String,Object> setup(@RequestBody Map<String,Object>b){var u=db.get("users",Security.user().id());require(encoder.matches(str(b,"password"),str(u,"password_hash")),"Contraseña incorrecta");require(!Boolean.TRUE.equals(u.get("totp_enabled")),"Desactiva primero el autenticador actual");String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";var random=new java.security.SecureRandom();StringBuilder key=new StringBuilder();for(int i=0;i<32;i++)key.append(alphabet.charAt(random.nextInt(32)));db.update("users",Security.user().id(),map("totp_secret",key.toString()));return map("secret",key.toString());}
 @PostMapping("/totp/enable")public void enable(@RequestBody Map<String,Object>b){var u=db.get("users",Security.user().id());require(validTotp(str(u,"totp_secret"),str(b,"otp")),"Código inválido");db.update("users",Security.user().id(),map("totp_enabled",true));access.audit("2FA","users",Security.user().id(),"Autenticador activado");}
 @PostMapping("/totp/disable")public void disable(@RequestBody Map<String,Object>b){var u=db.get("users",Security.user().id());require(encoder.matches(str(b,"password"),str(u,"password_hash"))&&validTotp(str(u,"totp_secret"),str(b,"otp")),"Contraseña o código inválidos");db.update("users",Security.user().id(),map("totp_enabled",false,"totp_secret",null));}
 static boolean validTotp(String key,String value){if(key.length()!=32||!value.matches("\\d{6}"))return false;try{byte[] bytes=new byte[20];int buffer=0,bits=0,n=0;for(char c:key.toCharArray()){int v="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567".indexOf(c);if(v<0)return false;buffer=(buffer<<5)|v;bits+=5;if(bits>=8){bits-=8;bytes[n++]=(byte)(buffer>>bits);}}long step=Instant.now().getEpochSecond()/30;for(long k=step-1;k<=step+1;k++){Mac mac=Mac.getInstance("HmacSHA1");mac.init(new SecretKeySpec(bytes,"HmacSHA1"));byte[] h=mac.doFinal(java.nio.ByteBuffer.allocate(8).putLong(k).array());int o=h[h.length-1]&15;int x=((h[o]&127)<<24)|((h[o+1]&255)<<16)|((h[o+2]&255)<<8)|(h[o+3]&255);if(String.format("%06d",x%1000000).equals(value))return true;}}catch(Exception ignored){}return false;}
}
